	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 20; ;
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 21; ; HuC's old scrolling library is provided for use with existing HuC projects,
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 22; ; but it should preferably be avoided in new projects because it is slow and
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 23; ; forever limited by its choice to handle gaps between areas, and sorting.
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 24; ;
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 25; ; HuCC's new scrolling library puts the responibility for defining both gaps
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 26; ; and the display order into the project's hands, but in return it runs much
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 27; ; faster, using less than 1/6 of the processing time in VBLANK, and far less
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 28; ; time in the RCR interrputs themselves. It also supports the 2nd SuperGRAFX
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 29; ; screen layer, which HuC's old scrolling library ignores.
	.dbg	line,	"\huc\include\hucc\hucc-old-scroll.h", 30; ;
